import React, {useState} from 'react';
import api from '../../lib/api';
import { useNavigate } from 'react-router-dom';

export default function AdminLogin(){
  const [email,setEmail] = useState('');
  const [password,setPassword] = useState('');
  const nav = useNavigate();

  async function submit(e){
    e.preventDefault();
    try{
      const r = await api.post('/auth/login',{email,password});
      localStorage.setItem('hr_token', r.data.token);
      nav('/admin/products');
    }catch(err){
      alert('Login gagal');
    }
  }

  return (
    <div className="container py-16 max-w-md">
      <div className="flex items-center justify-center gap-2 mb-4">
        <a href="/login" className="btn btn-outline flex-1">Login Pembeli</a>
        <a href="/admin/login" className="btn btn-primary flex-1">Login Admin</a>
      </div>
      <h2 className="text-2xl font-semibold">Login Admin</h2>
      <form onSubmit={submit} className="mt-6 space-y-4">
        <div>
          <input className="input" value={email} onChange={e=>setEmail(e.target.value)} placeholder="email" />
        </div>
        <div>
          <input className="input" type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="password" />
        </div>
        <div>
          <button type="submit" className="btn btn-primary w-full">Login</button>
        </div>
      </form>
    </div>
  )
}
